def value_function(D: int) -> list[int]:
    """z(d) = max sum c_j x_j  s.t.  sum a_j x_j <= d,  x_j in {0, 1, 2, ...}, for d = 0..D."""
    z = [0] * (D + 1)
    for d in range(1, D + 1):
        z[d] = max([z[d - 1]] + [z[d - a] + c for a, c in zip(weeks, worth) if a <= d])
    return z

